import { createClient } from 'supabase';
const pois=(l:number,k:number)=>Math.exp(-l)*Math.pow(l,k)/factorial(k); const factorial=(n:number)=>{let x=1;for(let i=2;i<=n;i++)x*=i;return x}; const cl=(x:number,a=0,b=1)=>Math.max(a,Math.min(b,x));
Deno.serve(async req=>{try{const b=await req.json().catch(()=>({})); const gw=Number(b.gameweek||1); const ks=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}'); const sb=createClient(Deno.env.get('SUPABASE_URL')!,ks.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}}); const {data:mv}=await sb.from('model_versions').select('id,version').eq('is_active',true).single(); if(!mv) throw new Error('active model missing'); const {data:latest}=await sb.from('model_predictions').select('generated_at').eq('model_version_id',mv.id).eq('gameweek',gw).order('generated_at',{ascending:false}).limit(1).maybeSingle(); if(!latest) throw new Error('no current model predictions'); const [{data:matches},{data:preds},{data:players},{data:teams}]=await Promise.all([sb.from('matches').select('id,gameweek,kickoff_time,home_team_id,away_team_id').eq('source','fpl').eq('gameweek',gw),sb.from('model_predictions').select('match_id,player_id,confidence,features').eq('model_version_id',mv.id).eq('gameweek',gw).eq('generated_at',latest.generated_at),sb.from('players').select('id,team_id'),sb.from('teams').select('id,name,short_name')]); const pmap=new Map((players||[]).map((p:any)=>[+p.id,+p.team_id])),tmap=new Map((teams||[]).map((t:any)=>[+t.id,t])); const now=new Date(),rows:any[]=[]; for(const m of matches||[]){if(new Date(m.kickoff_time)<=now) continue; const mp=(preds||[]).filter((x:any)=>+x.match_id===+m.id); const hp=mp.find((x:any)=>pmap.get(+x.player_id)===+m.home_team_id),ap=mp.find((x:any)=>pmap.get(+x.player_id)===+m.away_team_id); if(!hp||!ap)continue; const hl=Number(hp.features?.team_lambda),al=Number(ap.features?.team_lambda); if(!Number.isFinite(hl)||!Number.isFinite(al))continue; const score:any={},list:any[]=[]; let home=0,draw=0,away=0,over25=0,btts=0; for(let h=0;h<=7;h++)for(let a=0;a<=7;a++){const pr=pois(hl,h)*pois(al,a); score[`${h}-${a}`]=+pr.toFixed(6); list.push({score:`${h}-${a}`,prob:+pr.toFixed(6)}); if(h>a)home+=pr; else if(h===a)draw+=pr; else away+=pr; if(h+a>=3)over25+=pr; if(h>0&&a>0)btts+=pr;} list.sort((a,b)=>b.prob-a.prob); const hc=Math.exp(-al),ac=Math.exp(-hl),avgConf=mp.length?mp.reduce((s:any,x:any)=>s+Number(x.confidence||0),0)/mp.length:.5; const prevQ=await sb.from('fixture_prediction_snapshots').select('home_lambda,away_lambda,captured_at').eq('match_id',m.id).eq('is_pre_kickoff',true).order('captured_at',{ascending:false}).limit(1).maybeSingle(); const prev=prevQ.data; const reasons:any[]=[]; if(prev){const dh=hl-Number(prev.home_lambda),da=al-Number(prev.away_lambda); if(Math.abs(dh)>=.03) reasons.push({type:'home_lambda',from:+Number(prev.home_lambda).toFixed(3),to:+hl.toFixed(3),delta:+dh.toFixed(3)}); if(Math.abs(da)>=.03) reasons.push({type:'away_lambda',from:+Number(prev.away_lambda).toFixed(3),to:+al.toFixed(3),delta:+da.toFixed(3)});} else reasons.push({type:'initial_snapshot'}); rows.push({match_id:m.id,gameweek:gw,model_version_id:mv.id,captured_at:now.toISOString(),kickoff_time:m.kickoff_time,is_pre_kickoff:true,frozen:false,home_lambda:+hl.toFixed(3),away_lambda:+al.toFixed(3),score_matrix:score,top_scorelines:list.slice(0,5),markets:{home_win:+home.toFixed(4),draw:+draw.toFixed(4),away_win:+away.toFixed(4),over_2_5:+over25.toFixed(4),under_2_5:+(1-over25).toFixed(4),btts_yes:+btts.toFixed(4),btts_no:+(1-btts).toFixed(4),home_clean_sheet:+hc.toFixed(4),away_clean_sheet:+ac.toFixed(4)},confidence:+cl(avgConf).toFixed(3),change_reasons:reasons,source_snapshot:{prediction_generated_at:latest.generated_at,engine:hp.features?.engine,model_version:mv.version,home_team:tmap.get(+m.home_team_id)?.name,away_team:tmap.get(+m.away_team_id)?.name}})} if(rows.length){const {error}=await sb.from('fixture_prediction_snapshots').insert(rows);if(error)throw error} return Response.json({ok:true,gameweek:gw,inserted:rows.length,model_version:mv.version,captured_at:now.toISOString()})}catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}});
